'use client';

import React from 'react';
import {
    BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
    XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend,
    AreaChart, Area
} from 'recharts';

export type ChartType = 'bar' | 'line' | 'pie' | 'area' | 'table';

interface ChartRendererProps {
    type: ChartType;
    data: any[];
    xAxis: string;
    yAxis: string;
    colors?: string[];
}

const DEFAULT_COLORS = ['#8b5cf6', '#22d3ee', '#f43f5e', '#10b981', '#f59e0b', '#6366f1', '#ec4899'];

export default function ChartRenderer({ type, data, xAxis, yAxis, colors = DEFAULT_COLORS }: ChartRendererProps) {
    const renderChart = () => {
        // Simple data validation
        if (!data || data.length === 0) return <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: 'var(--text-muted)' }}>No data available</div>;

        if (type === 'table') {
            const columns = Object.keys(data[0]);
            return (
                <div style={{ height: '100%', overflow: 'auto', borderRadius: '8px', border: '1px solid var(--border)', background: 'var(--surface)' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem', position: 'relative' }}>
                        <thead style={{ position: 'sticky', top: 0, background: 'var(--surface)', zIndex: 1, boxShadow: '0 1px 0 var(--border)' }}>
                            <tr>
                                {columns.map(col => (
                                    <th key={col} style={{ padding: '12px', textAlign: 'left', fontWeight: 600, color: 'var(--text-muted)', borderBottom: '1px solid var(--border)' }}>
                                        {col}
                                    </th>
                                ))}
                            </tr>
                        </thead>
                        <tbody>
                            {data.map((row, i) => (
                                <tr key={i} style={{ borderBottom: '1px solid var(--border)', transition: 'background 0.2s' }} className="table-row">
                                    {columns.map(col => (
                                        <td key={col} style={{ padding: '12px', color: 'var(--foreground)' }}>
                                            {typeof row[col] === 'number' ? row[col].toLocaleString() : String(row[col])}
                                        </td>
                                    ))}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    <style jsx>{`
                        .table-row:hover {
                            background: rgba(255, 255, 255, 0.02);
                        }
                    `}</style>
                </div>
            );
        }

        const commonProps = {
            data,
            margin: { top: 10, right: 10, left: 0, bottom: 0 }
        };

        const CustomTooltip = ({ active, payload, label }: { active?: boolean; payload?: any[]; label?: string }) => {
            if (active && payload && payload.length) {
                return (
                    <div className="glass-card" style={{ padding: '12px', border: '1px solid var(--border)', background: 'var(--surface)', fontSize: '0.875rem' }}>
                        <p style={{ fontWeight: 600, marginBottom: '4px' }}>{label}</p>
                        {payload.map((entry, index: number) => (
                            <p key={index} style={{ color: entry.color || entry.fill }}>
                                {entry.name}: <span style={{ fontWeight: 600 }}>{entry.value}</span>
                            </p>
                        ))}
                    </div>
                );
            }
            return null;
        };

        const getChart = () => {
            switch (type) {
                case 'bar':
                    return (
                        <BarChart {...commonProps}>
                            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={false} />
                            <XAxis dataKey={xAxis} stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <YAxis stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <Tooltip content={<CustomTooltip />} cursor={{ fill: 'rgba(255,255,255,0.02)' }} />
                            <Legend iconType="circle" />
                            <Bar dataKey={yAxis} fill="var(--primary)" radius={[4, 4, 0, 0]} animationDuration={1000} />
                        </BarChart>
                    );

                case 'line':
                    return (
                        <LineChart {...commonProps}>
                            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={false} />
                            <XAxis dataKey={xAxis} stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <YAxis stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <Tooltip content={<CustomTooltip />} />
                            <Legend iconType="circle" />
                            <Line
                                type="monotone"
                                dataKey={yAxis}
                                stroke="var(--accent)"
                                strokeWidth={3}
                                dot={{ r: 4, fill: 'var(--accent)', strokeWidth: 2, stroke: 'var(--background)' }}
                                activeDot={{ r: 6, strokeWidth: 0 }}
                                animationDuration={1000}
                            />
                        </LineChart>
                    );

                case 'area':
                    return (
                        <AreaChart {...commonProps}>
                            <defs>
                                <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="var(--primary)" stopOpacity={0.3} />
                                    <stop offset="95%" stopColor="var(--primary)" stopOpacity={0} />
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" vertical={false} />
                            <XAxis dataKey={xAxis} stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <YAxis stroke="var(--text-muted)" fontSize={11} tickLine={false} axisLine={false} />
                            <Tooltip content={<CustomTooltip />} />
                            <Legend iconType="circle" />
                            <Area
                                type="monotone"
                                dataKey={yAxis}
                                stroke="var(--primary)"
                                fillOpacity={1}
                                fill="url(#colorValue)"
                                strokeWidth={3}
                                animationDuration={1000}
                            />
                        </AreaChart>
                    );

                case 'pie':
                    return (
                        <PieChart>
                            <Pie
                                data={data}
                                dataKey={yAxis}
                                nameKey={xAxis}
                                cx="50%"
                                cy="50%"
                                innerRadius={60}
                                outerRadius={100}
                                paddingAngle={5}
                                labelLine={false}
                                animationDuration={1000}
                            >
                                {data.map((_, index) => (
                                    <Cell key={`cell-${index}`} fill={colors[index % colors.length]} stroke="transparent" />
                                ))}
                            </Pie>
                            <Tooltip content={<CustomTooltip />} />
                            <Legend iconType="circle" layout="vertical" align="right" verticalAlign="middle" />
                        </PieChart>
                    );

                default:
                    return null;
            }
        };

        return (
            <ResponsiveContainer width="100%" height="100%">
                {getChart() || <div style={{ textAlign: 'center', paddingTop: '20%' }}>Chart type not supported</div>}
            </ResponsiveContainer>
        );
    };

    return (
        <div style={{ width: '100%', height: '100%', minHeight: '300px' }}>
            {renderChart()}
        </div>
    );
}
