'use client';

import React, { useState, useEffect } from 'react';
import Navbar from '@/components/layout/Navbar';
import FileDropzone from '@/components/upload/FileDropzone';
import { profileFile, profileFromUrl } from '@/lib/profiler';
import { ArrowRight, Clock, FileText, Plus, Database } from 'lucide-react';
import ReportCanvas from './canvas/ReportCanvas';
import DataTable from '@/components/ui/DataTable';
import { supabase } from '@/lib/supabase';
import { getDatasets, uploadFile, saveDataset, SavedDataset } from '@/lib/persistence';
import { User } from '@supabase/supabase-js';

export default function Dashboard() {
    const [step, setStep] = useState<'upload' | 'profiling' | 'canvas'>('upload');
    const [view, setView] = useState<'stats' | 'preview'>('preview');
    const [dataset, setDataset] = useState<any>(null);
    const [isProfiling, setIsProfiling] = useState(false);
    const [user, setUser] = useState<User | null>(null);
    const [savedDatasets, setSavedDatasets] = useState<SavedDataset[]>([]);
    const [isLoadingSaved, setIsLoadingSaved] = useState(false);

    useEffect(() => {
        // Track user session
        supabase.auth.getSession().then(({ data: { session } }) => {
            setUser(session?.user ?? null);
            if (session?.user) fetchSavedDatasets();
        });

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null);
            if (session?.user) fetchSavedDatasets();
            else setSavedDatasets([]);
        });

        return () => subscription.unsubscribe();
    }, []);

    const fetchSavedDatasets = async () => {
        setIsLoadingSaved(true);
        const data = await getDatasets();
        setSavedDatasets(data);
        setIsLoadingSaved(false);
    };

    const handleFileSelect = async (file: File) => {
        setIsProfiling(true);
        try {
            const profile = await profileFile(file);
            const datasetData = { name: file.name, ...profile };

            setDataset(datasetData);
            setStep('profiling');

            // Save to persistence if logged in
            if (user) {
                const url = await uploadFile(file, user.id);
                if (url) {
                    const savedDs = await saveDataset({
                        user_id: user.id,
                        name: file.name,
                        file_url: url,
                        columns: profile.columns,
                        stats: profile.stats
                    });
                    setDataset({ id: savedDs.id, name: file.name, ...profile });
                    fetchSavedDatasets(); // Refresh list
                }
            }
        } catch (err) {
            console.error('Error profiling file:', err);
            alert('Failed to process file. Check console for details.');
        } finally {
            setIsProfiling(false);
        }
    };

    const handleLoadSavedDataset = async (saved: SavedDataset) => {
        setIsProfiling(true);
        try {
            const profile = await profileFromUrl(saved.file_url, saved.name);
            setDataset({ id: saved.id, name: saved.name, ...profile });
            setStep('profiling');
        } catch (err) {
            console.error('Error loading saved dataset:', err);
            alert('Failed to load saved dataset.');
        } finally {
            setIsProfiling(false);
        }
    };

    return (
        <div className="main-container">
            <Navbar />

            <main style={{ flex: 1, padding: '40px 24px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
                {step === 'upload' && (
                    <div style={{ marginTop: '40px' }}>
                        <div style={{ textAlign: 'center', marginBottom: '60px' }}>
                            <h2 style={{ fontSize: '3rem', marginBottom: '16px' }} className="gradient-text">
                                {isProfiling ? 'Processing your data...' : 'Analyze, Visualize, Report.'}
                            </h2>
                            <p style={{ color: 'var(--text-muted)', fontSize: '1.125rem', maxWidth: '600px', margin: '0 auto' }}>
                                Upload your CSV, Excel or JSON files and transform them into actionable insights instantly.
                            </p>
                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: user && savedDatasets.length > 0 ? '1fr 350px' : '1fr', gap: '40px', alignItems: 'start' }}>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
                                <FileDropzone onFileSelect={handleFileSelect} />

                                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginTop: '20px' }}>
                                    {[
                                        { title: 'Fast DuckDB Engine', desc: 'Process millions of rows in seconds right in your browser.', icon: <Database size={20} /> },
                                        { title: 'Smart Profiling', desc: 'Automatic detection of types, distributions and outliers.', icon: <Plus size={20} /> },
                                        { title: 'Visual Designer', desc: 'Drag-and-drop canvas for beautiful, interactive reports.', icon: <FileText size={20} /> }
                                    ].map((feature, i) => (
                                        <div key={i} className="glass-card" style={{ padding: '24px' }}>
                                            <div style={{ color: 'var(--primary)', marginBottom: '16px' }}>{feature.icon}</div>
                                            <h4 style={{ fontWeight: 600, marginBottom: '8px' }}>{feature.title}</h4>
                                            <p style={{ fontSize: '0.875rem', color: 'var(--text-muted)', lineHeight: 1.5 }}>{feature.desc}</p>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {user && savedDatasets.length > 0 && (
                                <div className="glass-card" style={{ padding: '24px', height: 'fit-content' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '20px' }}>
                                        <Clock size={18} className="text-primary" />
                                        <h3 style={{ fontSize: '1rem', fontWeight: 600 }}>Recent Datasets</h3>
                                    </div>

                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                        {savedDatasets.slice(0, 5).map(ds => (
                                            <button
                                                key={ds.id}
                                                onClick={() => handleLoadSavedDataset(ds)}
                                                className="saved-dataset-item"
                                                style={{
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: '12px',
                                                    padding: '12px',
                                                    background: 'var(--surface)',
                                                    border: '1px solid var(--border)',
                                                    borderRadius: '8px',
                                                    width: '100%',
                                                    textAlign: 'left',
                                                    cursor: 'pointer',
                                                    transition: 'all 0.2s',
                                                    color: 'var(--foreground)'
                                                }}
                                            >
                                                <div style={{ background: 'var(--background)', padding: '8px', borderRadius: '6px' }}>
                                                    <FileText size={16} color="var(--primary)" />
                                                </div>
                                                <div style={{ flex: 1, overflow: 'hidden' }}>
                                                    <p style={{ fontSize: '0.875rem', fontWeight: 500, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                        {ds.name}
                                                    </p>
                                                    <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                                                        {new Date(ds.created_at).toLocaleDateString()}
                                                    </p>
                                                </div>
                                            </button>
                                        ))}
                                    </div>

                                    <style jsx>{`
                                        .saved-dataset-item:hover {
                                            border-color: var(--primary);
                                            transform: translateX(4px);
                                            background: var(--surface-light);
                                        }
                                    `}</style>
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {step === 'profiling' && dataset && (
                    <div className="animate-in fade-in duration-500">
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '32px' }}>
                            <div>
                                <hgroup>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                                        <button onClick={() => setStep('upload')} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', fontSize: '0.875rem', padding: 0 }}>
                                            Datasets
                                        </button>
                                        <span style={{ color: 'var(--text-muted)' }}>/</span>
                                        <h2 style={{ fontSize: '1.5rem', fontWeight: 600 }}>{dataset.name}</h2>
                                    </div>
                                    <div style={{ display: 'flex', gap: '8px' }}>
                                        <button
                                            onClick={() => setView('preview')}
                                            style={{
                                                background: view === 'preview' ? 'var(--primary)' : 'var(--surface)',
                                                padding: '6px 16px',
                                                borderRadius: '20px',
                                                color: view === 'preview' ? 'white' : 'var(--text-muted)',
                                                fontSize: '0.8125rem',
                                                fontWeight: 500,
                                                border: 'none',
                                                cursor: 'pointer',
                                                transition: 'all 0.2s'
                                            }}
                                        >
                                            Preview
                                        </button>
                                        <button
                                            onClick={() => setView('stats')}
                                            style={{
                                                background: view === 'stats' ? 'var(--primary)' : 'var(--surface)',
                                                padding: '6px 16px',
                                                borderRadius: '20px',
                                                color: view === 'stats' ? 'white' : 'var(--text-muted)',
                                                fontSize: '0.8125rem',
                                                fontWeight: 500,
                                                border: 'none',
                                                cursor: 'pointer',
                                                transition: 'all 0.2s'
                                            }}
                                        >
                                            Statistics
                                        </button>
                                    </div>
                                </hgroup>
                            </div>
                            <button
                                className="btn-primary"
                                style={{ padding: '12px 24px', display: 'flex', alignItems: 'center', gap: '8px', borderRadius: '12px' }}
                                onClick={() => setStep('canvas')}
                            >
                                Build Magic Report <ArrowRight size={18} />
                            </button>
                        </div>

                        {view === 'stats' ? (
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
                                {dataset.stats.map((col: any) => (
                                    <div key={col.column} className="glass-card" style={{ padding: '24px' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', marginBottom: '20px' }}>
                                            <span style={{ fontWeight: 600, fontSize: '1rem', color: 'var(--foreground)' }}>{col.column}</span>
                                            <span style={{ fontSize: '0.7rem', fontWeight: 600, color: 'var(--primary)', background: 'var(--primary-glow)', padding: '4px 8px', borderRadius: '6px', textTransform: 'uppercase' }}>
                                                {col.type}
                                            </span>
                                        </div>

                                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                                            <div>
                                                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: '4px' }}>Unique Values</p>
                                                <p style={{ fontWeight: 600, fontSize: '1.25rem' }}>{col.unique.toLocaleString()}</p>
                                            </div>
                                            <div>
                                                <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: '4px' }}>Missing (Nulls)</p>
                                                <p style={{ fontWeight: 600, fontSize: '1.25rem', color: col.nulls > 0 ? '#f87171' : 'var(--foreground)' }}>{col.nulls.toLocaleString()}</p>
                                            </div>
                                            {col.min != null && (
                                                <div style={{ gridColumn: 'span 2', padding: '12px', background: 'var(--surface)', borderRadius: '8px' }}>
                                                    <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginBottom: '8px' }}>Value Range</p>
                                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                        <span style={{ fontWeight: 500, fontSize: '0.875rem' }}>{col.min}</span>
                                                        <div style={{ height: '4px', flex: 1, margin: '0 12px', background: 'var(--border)', borderRadius: '2px', position: 'relative' }}>
                                                            <div style={{ position: 'absolute', inset: 0, background: 'var(--primary)', opacity: 0.3, borderRadius: '2px' }} />
                                                        </div>
                                                        <span style={{ fontWeight: 500, fontSize: '0.875rem' }}>{col.max}</span>
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="glass-card" style={{ padding: '2px', overflow: 'hidden' }}>
                                <DataTable columns={dataset.columns} data={dataset.preview} />
                            </div>
                        )}
                    </div>
                )}

                {step === 'canvas' && dataset && (
                    <ReportCanvas dataset={dataset} />
                )}
            </main>
        </div>
    );
}
